/**
 * Weather glyphs — Meteocons (line style) by Bas Milius, MIT licensed.
 * https://github.com/basmilius/weather-icons
 *
 * Full-color weather icons (gold sun, blue rain) with real day/night variants
 * and rain/snow intensities that Tabler doesn't carry. The near-white cloud
 * tones are nudged to a mid steel-blue so clouds read on the frosted-white
 * weather card as well as in dark mode. Each icon is a fixed-palette SVG;
 * internal mask/clip ids are namespaced per instance so repeated icons never
 * clash.
 */
import { useId } from "react";
import type { ReactElement } from "react";

export type WeatherGlyph = (props: {
  size?: number;
  className?: string;
}) => ReactElement;

/** Wrap a raw Meteocons SVG body in a sized, id-namespaced <svg>. */
function meteocon(body: string): WeatherGlyph {
  return function WeatherGlyph({ size = 24, className }) {
    const uid = useId().replace(/:/g, "");
    const svg = body
      .replace(/id="([^"]+)"/g, `id="$1-${uid}"`)
      .replace(/url\(#([^)]+)\)/g, `url(#$1-${uid})`);
    return (
      <svg
        viewBox="0 0 128 128"
        width={size}
        height={size}
        fill="none"
        aria-hidden
        className={className}
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    );
  };
}

